 function monta_grid($linhas = 0)
 {
   global $nm_saida;

   clearstatcache();
   $this->NM_cor_embutida();
   $this->hide_nested_grid_action_buttons = false;
   $this->All_nested      = array();
   $this->All_nested_line = array();
   if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['grid_pesq'])) {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['grid_pesq'] = array();
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['embutida_init'])
   { 
        return; 
   } 
   $this->inicializa();
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['charts_html'] = '';
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['embutida'])
   { 
       $this->Lin_impressas = 0;
       $this->Lin_final     = FALSE;
       $this->grid();
       $this->nm_fim_grid();
   } 
   else 
   { 
    if (strpos(" " . $this->Ini->SC_module_export, "grid") !== false) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['proc_pdf'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['proc_pdf_vert'])
            {
            } 
            else
            {
       $nm_saida->saida("                  <TR>\r\n");
       $nm_saida->saida("                  <TD id='sc_grid_content' style='padding: 0px;' colspan=1>\r\n");
            } 
       $nm_saida->saida("    <table width='100%' cellspacing=0 cellpadding=0>\r\n");
       $nmgrp_apl_opcao= (isset($_SESSION['sc_session']['scriptcase']['embutida_form_pdf']['grid_confirmacao_viagem_rsvp_2'])) ? "pdf" : $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao'];
       $this->nmgp_barra_sub_cons = false;
       if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['SC_sub_toolbar'])) {
           if (!$_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['ExportPrtFrame']) {
               $this->nmgp_tool_subcons();
               $this->nmgp_embbed_placeholder_top();
           } 
           $this->nmgp_barra_sub_cons = true;
       } 
       if ($nmgrp_apl_opcao != "pdf" && !$this->nmgp_barra_sub_cons)
       { 
           $this->nmgp_barra_top();
       } 
       unset ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['save_grid']);
       $this->grid();
       if ($nmgrp_apl_opcao != "pdf" && !$this->nmgp_barra_sub_cons)
       { 
           $this->nmgp_barra_bot();
       } 
       $nm_saida->saida("   </table>\r\n");
       $nm_saida->saida("  </TD>\r\n");
       $nm_saida->saida(" </TR>\r\n");
       $this->rodape();
    }
       if (strpos(" " . $this->Ini->SC_module_export, "resume") !== false)
       { 
           $Gera_res = true;
       } 
       else 
       { 
           $Gera_res = false;
       } 
       if (strpos(" " . $this->Ini->SC_module_export, "chart") !== false)
       { 
           $Gera_graf = true;
       } 
       else 
       { 
           $Gera_graf = false;
       } 
       if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['print_all'] && empty($this->nm_grid_sem_reg) && ($Gera_res || $Gera_graf) && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['SC_Ind_Groupby'] != "sc_free_total")
       { 
           $this->Res->monta_html_ini_pdf();
           $this->Res->monta_resumo();
           $this->Res->monta_html_fim_pdf();
           if ($Gera_graf)
           {
               $this->grafico_pdf();
           }
       } 
       $flag_apaga_pdf_log = TRUE;
       if (!$this->Print_All && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao'] == "pdf")
       { 
           $flag_apaga_pdf_log = FALSE;
       } 
       $this->nm_fim_grid($flag_apaga_pdf_log);
       if (!$this->Print_All && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao'] == "pdf")
       { 
           $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao'] = "igual";
       } 
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao_print'] == "print")
   {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao'] = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao_ant'];
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao_print'] = "";
   }
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao_ant'] = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_confirmacao_viagem_rsvp_2']['opcao'];
 }
 function resume($linhas = 0)
 {
    $this->Lin_impressas = 0;
    $this->Lin_final     = FALSE;
    $this->grid($linhas);
 }
